"use client";

import { BLUEPRINT_SEED } from "@/app/lib/blueprintSeed";
import { useCountUp } from "@/app/lib/useCountUp";
import { formatINR } from "@/app/lib/formatINR";
import { motion } from "framer-motion";
import { usePrefersReducedMotion } from "@/app/lib/usePrefersReducedMotion";
import { TiltCard } from "./TiltCard";

/** Headline figure on the Finance landing tab — total balance, counting
    up on load with a gradient fill and neon glow on glass. Seed (P8). */
export function TotalBalanceReadout() {
  const reduce = usePrefersReducedMotion();
  const shown = useCountUp(BLUEPRINT_SEED.totalBalance);

  return (
    <TiltCard className="spin-border">
      <div aria-label="Total balance">
        <p className="num text-[10px] tracking-[0.24em] text-dim">TOTAL BALANCE</p>
        <p className="num mt-1 text-5xl font-bold grad-text-wealth neon-glow-amber">
          {formatINR(Math.round(shown))}
        </p>
        <motion.div
          className="mt-4 h-[3px] rounded"
          style={{ transformOrigin: "left", background: "var(--grad-wealth)" }}
          initial={{ scaleX: reduce ? 1 : 0 }}
          animate={{ scaleX: 1 }}
          transition={{ duration: 1.1, ease: [0.16, 1, 0.3, 1] }}
        />
      </div>
    </TiltCard>
  );
}
